def search_crates(query, page=None, perPage=None, **_extra):
    import json, os, datetime, time, re, hashlib
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0348000" if __import__("os").path.isdir("./environment_mix/0348000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- request log / quotas ---
    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    endpoint = "search_crates"
    # Simple server-wide rate limit: 120 req/min across all callers (ambient auth).
    window_s = 60
    limit = 120
    cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)).replace(microsecond=0).isoformat() + "Z"
    recent = 0
    for r in logs:
        try:
            if r.get("endpoint") == endpoint and isinstance(r.get("timestamp"), str) and r["timestamp"] >= cutoff:
                recent += 1
        except Exception:
            continue
    if recent >= limit:
        latency_ms = int((time.time() - start) * 1000)
        logs.append({
            "id": "rl_" + hashlib.sha256((endpoint + now + str(len(logs))).encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential": None,
            "status": "RATE_LIMIT",
            "latency_ms": latency_ms,
            "timestamp": now
        })
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    def _log(status):
        latency_ms = int((time.time() - start) * 1000)
        logs.append({
            "id": "rl_" + hashlib.sha256((endpoint + now + status + str(len(logs))).encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential": None,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": now
        })
        _save("request_logs.json", logs)

    # --- validation ---
    if not isinstance(query, str) or len(query.strip()) < 1:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    q = query.strip()

    if page is None:
        page_i = 1
    else:
        if not isinstance(page, (int, float)) or isinstance(page, bool):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page must be a number")
        if int(page) != page:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "page must be an integer")
        page_i = int(page)
    if perPage is None:
        per_i = 10
    else:
        if not isinstance(perPage, (int, float)) or isinstance(perPage, bool):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "perPage must be a number")
        if int(perPage) != perPage:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "perPage must be an integer")
        per_i = int(perPage)

    if page_i < 1:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page must be >= 1")
    if per_i < 1 or per_i > 100:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "perPage must be between 1 and 100")

    crates = _load("crates.json")
    if not isinstance(crates, list):
        _log("INTERNAL_ERROR")
        return _err("INTERNAL_ERROR", "Failed to load crates index")

    # --- search ---
    q_l = q.lower()
    terms = [t for t in re.split(r"\s+", q_l) if t]
    def _hay(c):
        parts = [
            str(c.get("name") or ""),
            str(c.get("description") or ""),
            str(c.get("repository_url") or "")
        ]
        return " ".join(parts).lower()

    matches = []
    for c in crates:
        if not isinstance(c, dict):
            continue
        if c.get("status") != "active":
            continue
        hay = _hay(c)
        if all(t in hay for t in terms):
            # Simple ranking: occurrences of full query + sum occurrences of terms, prefer name hits.
            name = (c.get("name") or "").lower()
            score = 0
            score += hay.count(q_l) * 10
            for t in terms:
                score += hay.count(t)
                if t in name:
                    score += 3
            matches.append((score, c.get("name") or "", c))

    matches.sort(key=lambda x: (-x[0], x[1]))
    total = len(matches)
    start_idx = (page_i - 1) * per_i
    end_idx = start_idx + per_i
    page_rows = [m[2] for m in matches[start_idx:end_idx]]

    has_more = end_idx < total

    _log("OK")
    return {
        "data": page_rows,
        "meta": {
            "query": q,
            "page": page_i,
            "per_page": per_i,
            "total": total,
            "has_more": has_more,
            "next_page": (page_i + 1) if has_more else None
        }
    }

