    window_s = 60
    limit = 120
    cutoff = (datetime.datetime.utcnow() - datetime.timedelta(seconds=window_s)).replace(microsecond=0).isoformat() + "Z"
    recent = 0
    for r in logs:
        try:
            if r.get("endpoint") == endpoint and isinstance(r.get("timestamp"), str) and r["timestamp"] >= cutoff:
                recent += 1
        except Exception:
            continue
    if recent >= limit:
        latency_ms = int((time.time() - start) * 1000)
        logs.append({
            "id": "rl_" + hashlib.sha256((endpoint + now + str(len(logs))).encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential": None,
            "status": "RATE_LIMIT",
            "latency_ms": latency_ms,
            "timestamp": now
        })
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    def _log(status):
        latency_ms = int((time.time() - start) * 1000)
        logs.append({
            "id": "rl_" + hashlib.sha256((endpoint + now + status + str(len(logs))).encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential": None,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": now
        })
        _save("request_logs.json", logs)

    if not isinstance(crateName, str) or len(crateName.strip()) < 1:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "crateName must be a non-empty string")
    name = crateName.strip()
    if version is not None:
        if not isinstance(version, str) or len(version.strip()) < 1:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "version must be a non-empty string when provided")
        ver = version.strip()
        # light semver-ish validation
        if not re.match(r"^[0-9A-Za-z][0-9A-Za-z\.\-\+\_]*$", ver):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "version is malformed")
    else:
        ver = None

    crates = _load("crates.json")
    if not isinstance(crates, list):
        _log("INTERNAL_ERROR")
        return _err("INTERNAL_ERROR", "Failed to load crates")
    crate = None
    for c in crates:
        if isinstance(c, dict) and c.get("name") == name:
            crate = c
            break
    if not crate:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Crate not found")

    if ver is None:
        ver = crate.get("latest_version")
        if ver is None:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Crate has no latest_version")

    versions = _load("crate_versions.json")
    if not isinstance(versions, list):
        _log("INTERNAL_ERROR")
        return _err("INTERNAL_ERROR", "Failed to load crate versions")

    cv = None
    for row in versions:
        if isinstance(row, dict) and row.get("crate_id") == crate.get("id") and row.get("version") == ver:
            cv = row
            break
    if not cv:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Crate version not found")

    pages = _load("doc_pages.json")
    if not isinstance(pages, list):
        _log("INTERNAL_ERROR")
        return _err("INTERNAL_ERROR", "Failed to load documentation pages")

    preferred = ["index.html", f"{name}/index.html"]
    page = None
    for pth in preferred:
        for p in pages:
            if not isinstance(p, dict):
                continue
            if p.get("crate_version_id") == cv.get("id") and p.get("path") == pth and p.get("status") == "present":
                page = p
                break
        if page:
            break

    if not page:
        # Business rule: if none exists and crate_versions.status != 'indexed', return indexing/unavailable error.
        if cv.get("status") != "indexed":
            _log("CONFLICT")
            return _err("CONFLICT", "Documentation is not available yet", crate_version_status=cv.get("status"))
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Crate documentation entrypoint not found")

    _log("OK")
    return {
        "data": {
            "crate": {"id": crate.get("id"), "name": crate.get("name"), "latest_version": crate.get("latest_version")},
            "crate_version": {"id": cv.get("id"), "version": cv.get("version"), "status": cv.get("status"), "indexed_at": cv.get("indexed_at")},
            "page": page
        }
    }

def get_type_info(crateName, path, version=None, **_extra):
    import json, os, datetime, time, hashlib, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0348000" if __import__("os").path.isdir("./environment_mix/0348000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    logs = _load("request_logs.json")
    if not isinstance(logs, list):
        logs = []
    endpoint = "get_type_info"
    window_s = 60
    limit = 180
    cutoff = (now_dt - datetime.timedelta(seconds=window_s)).isoformat() + "Z"
    recent = 0
    for r in logs:
        try:
            if r.get("endpoint") == endpoint and isinstance(r.get("timestamp"), str) and r["timestamp"] >= cutoff:
                recent += 1
        except Exception:
            continue
    if recent >= limit:
        latency_ms = int((time.time() - start) * 1000)
        logs.append({
            "id": "rl_" + hashlib.sha256((endpoint + now + str(len(logs))).encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential": None,
            "status": "RATE_LIMIT",
            "latency_ms": latency_ms,
            "timestamp": now
        })
        _save("request_logs.json", logs)
        return _err("RATE_LIMIT", "Rate limit exceeded")

    def _log(status):
        latency_ms = int((time.time() - start) * 1000)
        logs.append({
            "id": "rl_" + hashlib.sha256((endpoint + now + status + str(len(logs))).encode("utf-8")).hexdigest()[:16],
            "endpoint": endpoint,
            "credential": None,
            "status": status,
            "latency_ms": latency_ms,
            "timestamp": now
        })
        _save("request_logs.json", logs)

    if not isinstance(crateName, str) or len(crateName.strip()) < 1:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "crateName must be a non-empty string")
    name = crateName.strip()

    if not isinstance(path, str) or len(path.strip()) < 1:
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "path must be a non-empty string")
    pth = path.strip()

    # Path normalization rule: no leading slash, no '..' segments.
    if pth.startswith("/"):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "path must be rustdoc-relative (must not start with '/')")
    segs = [s for s in pth.split("/") if s != ""]
    if any(s == ".." for s in segs):
        _log("VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "path must not contain '..' segments")

    if version is not None:
        if not isinstance(version, str) or len(version.strip()) < 1:
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "version must be a non-empty string when provided")
        ver = version.strip()
        if not re.match(r"^[0-9A-Za-z][0-9A-Za-z\.\-\+\_]*$", ver):
            _log("VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "version is malformed")
    else:
        ver = None

    crates = _load("crates.json")
    if not isinstance(crates, list):
        _log("INTERNAL_ERROR")
        return _err("INTERNAL_ERROR", "Failed to load crates")
    crate = None
    for c in crates:
        if isinstance(c, dict) and c.get("name") == name:
            crate = c
            break
    if not crate:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Crate not found")

    if ver is None:
        ver = crate.get("latest_version")
        if ver is None:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Crate has no latest_version")

    versions = _load("crate_versions.json")
    if not isinstance(versions, list):
        _log("INTERNAL_ERROR")
        return _err("INTERNAL_ERROR", "Failed to load crate versions")
    cv = None
    for row in versions:
        if isinstance(row, dict) and row.get("crate_id") == crate.get("id") and row.get("version") == ver:
            cv = row
            break
    if not cv:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Crate version not found")

    pages = _load("doc_pages.json")
    if not isinstance(pages, list):
        _log("INTERNAL_ERROR")
        return _err("INTERNAL_ERROR", "Failed to load documentation pages")

    # Find existing row by (crate_version_id, path)
    page_idx = None
    page = None
    for i, p in enumerate(pages):
        if not isinstance(p, dict):
            continue
        if p.get("crate_version_id") == cv.get("id") and p.get("path") == pth:
            page_idx = i
            page = p
            break

    if page and page.get("status") == "present":
        _log("OK")
        return {"data": {"crate_version": {"id": cv.get("id"), "version": cv.get("version"), "status": cv.get("status")}, "page": page}}

    # Lazy fetch/build only allowed when crate_versions.status in ('available','indexed')
    if cv.get("status") not in ("available", "indexed"):
        # If the page exists but missing/stale, still cannot fetch unless allowed.
        if page:
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Type page not available", page_status=page.get("status"), crate_version_status=cv.get("status"))
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Type page not found", crate_version_status=cv.get("status"))

    # Attempt lazy fetch/build.
    # Offline behavior: we can only "promote" an existing row with html to present; otherwise mark missing.
    changed = False
    if page:
        if page.get("html") and isinstance(page.get("html"), str) and len(page["html"]) >= 1 and page.get("content_sha256"):
            page["status"] = "present"
            page["fetched_at"] = now
            page["updated_at"] = now
            pages[page_idx] = page
            changed = True
            _save("doc_pages.json", pages)
            _log("OK")
            return {"data": {"crate_version": {"id": cv.get("id"), "version": cv.get("version"), "status": cv.get("status")}, "page": page}}
        else:
            page["status"] = "missing"
            page["fetched_at"] = now
            page["updated_at"] = now
            pages[page_idx] = page
            changed = True
            _save("doc_pages.json", pages)
            _log("NOT_FOUND")
            return _err("NOT_FOUND", "Type page not found")
    else:
        # Create a minimal missing row to reflect attempted fetch/build and cache miss outcome.
        # Enforce path constraints on write (already validated above).
        new_id = "dp_" + hashlib.sha256((cv.get("id", "") + "|" + pth + "|" + now).encode("utf-8")).hexdigest()[:24]
        missing = {
            "id": new_id,
            "crate_version_id": cv.get("id"),
            "path": pth,
            "page_kind": "other",
            "title": None,
            "html": "<missing/>",  # keep non-empty to satisfy schema constraint length(html) >= 1
            "content_sha256": hashlib.sha256(b"<missing/>").hexdigest(),
            "fetched_at": now,
            "status": "missing",
            "created_at": now,
            "updated_at": now
        }
        pages.append(missing)
        changed = True
        _save("doc_pages.json", pages)
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Type page not found")

    # Should not reach, but ensure no silent success.
    if changed:
        _log("NOT_FOUND")
        return _err("NOT_FOUND", "Type page not found")
    _log("INTERNAL_ERROR")
    return _err("INTERNAL_ERROR", "Unexpected state")

