def get_crate_versions(crateName, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0348000" if __import__("os").path.isdir("./environment_mix/0348000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, (int, float)):
            try:
                return datetime.datetime.utcfromtimestamp(v)
            except Exception:
                return None
        if not isinstance(v, str) or not v:
            return None
        s = v.strip()
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _audit(endpoint, status, credential_id=None, error_code=None, error_message=None, meta=None, start_ts=None):
        # If no request log exists in schema, do nothing.
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            path = os.path.join(_DB, fname)
            if os.path.exists(path):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                latency_ms = None
                if start_ts is not None:
                    latency_ms = int(max(0, (time.time() - start_ts) * 1000))
                row = {
                    "id": "req_" + str(int(time.time() * 1000)),
                    "endpoint": endpoint,
                    "status": status,
                    "credential_id": credential_id,
                    "error_code": error_code,
                    "error_message": error_message,
                    "latency_ms": latency_ms,
                    "timestamp": _now_iso(),
                    "meta": meta or {},
                }
                logs.append(row)
                _save(fname, logs)
                break

    start = time.time()
    endpoint = "get_crate_versions"

    # Validate
    if not isinstance(crateName, str) or len(crateName) < 1:
        _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="crateName must be a non-empty string", start_ts=start)
        return _err("VALIDATION_ERROR", "crateName must be a non-empty string")

    crates = _load("crates.json")
    crate = None
    for c in crates:
        if isinstance(c, dict) and c.get("name") == crateName:
            crate = c
            break
    if not crate:
        _audit(endpoint, "error", error_code="NOT_FOUND", error_message="crate not found", start_ts=start)
        return _err("NOT_FOUND", "Crate not found")

    crate_versions = _load("crate_versions.json")
    rows = []
    for v in crate_versions:
        if not isinstance(v, dict):
            continue
        if v.get("crate_id") == crate.get("id"):
            rows.append(v)

    def _sort_key(v):
        dt = _parse_dt(v.get("published_at"))
        # published_at desc then version desc (string fallback)
        # If published_at missing, treat as very old.
        dt_key = dt if dt is not None else datetime.datetime(1970, 1, 1)
        ver = v.get("version") or ""
        return (dt_key, ver)

    rows.sort(key=_sort_key, reverse=True)

    resp = {
        "crate": {
            "id": crate.get("id"),
            "name": crate.get("name"),
            "latest_version": crate.get("latest_version"),
            "status": crate.get("status"),
        },
        "versions": rows,
        "count": len(rows),
    }
    _audit(endpoint, "ok", start_ts=start, meta={"crate_id": crate.get("id"), "count": len(rows)})
    return resp

def get_source_code(crateName, path, version=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0348000" if __import__("os").path.isdir("./environment_mix/0348000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _pick_logfile():
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return "request_logs.json"

    def _audit(endpoint, status, error_code=None, error_message=None, meta=None, start_ts=None):
        fname = _pick_logfile()
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        latency_ms = None
        if start_ts is not None:
            latency_ms = int(max(0, (time.time() - start_ts) * 1000))
        logs.append({
            "id": "req_" + str(int(time.time() * 1000)) + "_" + str(len(logs) + 1),
            "endpoint": endpoint,
            "status": status,
            "credential_id": None,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save(fname, logs)

    def _enforce_rate_limit(endpoint, start_ts):
        """
        Very small local/offline implementation:
        - 120 requests/min per process/store (global)
        - 10,000 requests/day per store (global)
        If the store already contains usage counters, advance them as well.
        """
        fname = _pick_logfile()
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        one_min_ago = now - datetime.timedelta(minutes=1)
        one_day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(ts):
            if not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    dt = datetime.datetime.fromisoformat(ts[:-1])
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    else:
                        dt = dt.astimezone(datetime.timezone.utc)
                else:
                    dt = datetime.datetime.fromisoformat(ts)
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    dt = dt.astimezone(datetime.timezone.utc)
                return dt
            except Exception:
                return None

        last_min = 0
        last_day = 0
        for r in logs:
            dt = _parse_ts(r.get("timestamp"))
            if not dt:
                continue
            if dt >= one_min_ago:
                last_min += 1
            if dt >= one_day_ago:
                last_day += 1

        if last_min >= 120:
            _audit(endpoint, "error", error_code="RATE_LIMIT", error_message="Rate limit exceeded (120 requests/min)", start_ts=start_ts)
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if last_day >= 10000:
            _audit(endpoint, "error", error_code="QUOTA_EXCEEDED", error_message="Daily quota exceeded (10000 requests/day)", start_ts=start_ts)
            return _err("QUOTA_EXCEEDED", "Quota exceeded")

        return None

    def _norm_path(p):
        # For this endpoint, validate against traversal/unsafe paths (business rule).
        # We also accept rustdoc-like paths passed mistakenly; but we still apply security constraints.
        if not isinstance(p, str) or not p.strip():
            return None
        p = p.strip()
        if p.startswith("/"):
            return None
        parts = p.split("/")
        if any(seg == ".." for seg in parts):
            return None
        if any(seg == "" for seg in parts):
            # disallow double slashes or trailing slash; treat as invalid path
            return None
        return p

    start = time.time()
    endpoint = "get_source_code"

    # Validate inputs
    if not isinstance(crateName, str) or len(crateName) < 1:
        _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="crateName must be a non-empty string", start_ts=start)
        return _err("VALIDATION_ERROR", "crateName must be a non-empty string")
    if not isinstance(path, str) or len(path) < 1:
        _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="path must be a non-empty string", start_ts=start)
        return _err("VALIDATION_ERROR", "path must be a non-empty string")
    norm_path = _norm_path(path)
    if norm_path is None:
        _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="path must not start with '/' or contain '..' segments", start_ts=start)
        return _err("VALIDATION_ERROR", "path must not start with '/' or contain '..' segments")

    if version is not None and (not isinstance(version, str) or not version.strip()):
        _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="version must be a non-empty string when provided", start_ts=start)
        return _err("VALIDATION_ERROR", "version must be a non-empty string when provided")

    rl = _enforce_rate_limit(endpoint, start)
    if rl:
        return rl

    crates = _load("crates.json")
    crate_versions = _load("crate_versions.json")
    source_files = _load("source_files.json")

    if not isinstance(crates, list):
        crates = []
    if not isinstance(crate_versions, list):
        crate_versions = []
    if not isinstance(source_files, list):
        source_files = []

    # Resolve crate by name (case-insensitive), prefer active, but allow disabled if that's all that exists.
    name_l = crateName.strip().lower()
    matching = [c for c in crates if isinstance(c, dict) and isinstance(c.get("name"), str) and c.get("name").lower() == name_l]
    if not matching:
        _audit(endpoint, "error", error_code="NOT_FOUND", error_message="Crate not found", start_ts=start, meta={"crateName": crateName})
        return _err("NOT_FOUND", "Crate not found")
    active = [c for c in matching if c.get("status") == "active"]
    crate = active[0] if active else matching[0]

    # Resolve crate version
    ver = version.strip() if isinstance(version, str) else None
    if ver is None:
        ver = crate.get("latest_version")
        if not ver:
            _audit(endpoint, "error", error_code="NOT_FOUND", error_message="Crate latest_version is null; version must be specified", start_ts=start, meta={"crateName": crateName})
            return _err("NOT_FOUND", "Crate version not found (latest_version is null)")
    # Find crate_version row by crate_id+version; do not fail due to unrelated crate picked.
    cvid_rows = [
        v for v in crate_versions
        if isinstance(v, dict) and v.get("crate_id") == crate.get("id") and v.get("version") == ver
    ]
    if not cvid_rows:
        # If crate selection (active/disabled) was wrong due to duplicate name (shouldn't happen), attempt any crate with this name that has the requested version.
        found = None
        for c in matching:
            for v in crate_versions:
                if isinstance(v, dict) and v.get("crate_id") == c.get("id") and v.get("version") == ver:
                    crate = c
                    found = v
                    break
            if found:
                break
        if not found:
            _audit(endpoint, "error", error_code="NOT_FOUND", error_message="Crate version not found", start_ts=start, meta={"crateName": crateName, "version": ver})
            return _err("NOT_FOUND", "Crate version not found")
        crate_version = found
    else:
        crate_version = cvid_rows[0]

    # Locate source file
    file_rows = [
        s for s in source_files
        if isinstance(s, dict)
        and s.get("crate_version_id") == crate_version.get("id")
        and s.get("path") == norm_path
    ]
    if not file_rows:
        _audit(endpoint, "error", error_code="NOT_FOUND", error_message="Source file not found", start_ts=start, meta={"crateName": crateName, "version": ver, "path": norm_path})
        return _err("NOT_FOUND", "Source file not found")
    src = file_rows[0]
    if src.get("status") != "present":
        _audit(endpoint, "error", error_code="NOT_FOUND", error_message="Source file not available", start_ts=start, meta={"crateName": crateName, "version": ver, "path": norm_path, "status": src.get("status")})
        return _err("NOT_FOUND", "Source file not found")

    # Return envelope
    body = {
        "crate": {"id": crate.get("id"), "name": crate.get("name")},
        "crate_version": {"id": crate_version.get("id"), "version": crate_version.get("version"), "status": crate_version.get("status"), "yanked": crate_version.get("yanked")},
        "source_file": {
            "id": src.get("id"),
            "path": src.get("path"),
            "language": src.get("language"),
            "content": src.get("content"),
            "content_sha256": src.get("content_sha256"),
            "size_bytes": src.get("size_bytes"),
            "status": src.get("status"),
            "created_at": src.get("created_at"),
            "updated_at": src.get("updated_at"),
        }
    }
    _audit(endpoint, "ok", start_ts=start, meta={"crate_id": crate.get("id"), "crate_version_id": crate_version.get("id"), "path": norm_path})
    return body

def search_symbols(crateName, query, version=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0348000" if __import__("os").path.isdir("./environment_mix/0348000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _audit(endpoint, status, credential_id=None, error_code=None, error_message=None, meta=None, start_ts=None):
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                logs = _load(fname)
                if not isinstance(logs, list):
                    logs = []
                latency_ms = None
                if start_ts is not None:
                    latency_ms = int(max(0, (time.time() - start_ts) * 1000))
                logs.append({
                    "id": "req_" + str(int(time.time() * 1000)),
                    "endpoint": endpoint,
                    "status": status,
                    "credential_id": credential_id,
                    "error_code": error_code,
                    "error_message": error_message,
                    "latency_ms": latency_ms,
                    "timestamp": _now_iso(),
                    "meta": meta or {},
                })
                _save(fname, logs)
                break

    start = time.time()
    endpoint = "search_symbols"

    # Validate
    if not isinstance(crateName, str) or len(crateName) < 1:
        _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="crateName must be a non-empty string", start_ts=start)
        return _err("VALIDATION_ERROR", "crateName must be a non-empty string")
    if not isinstance(query, str) or len(query) < 1:
        _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="query must be a non-empty string", start_ts=start)
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    if version is not None and (not isinstance(version, str) or len(version) < 1):
        _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="version must be a non-empty string when provided", start_ts=start)
        return _err("VALIDATION_ERROR", "version must be a non-empty string when provided")

    # Basic version sanity (not full semver parse)
    if version is not None and not re.match(r"^[0-9A-Za-z\.\-\+\_]+$", version):
        _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="version is malformed", start_ts=start)
        return _err("VALIDATION_ERROR", "version is malformed")

    crates = _load("crates.json")
    crate = None
    for c in crates:
        if isinstance(c, dict) and c.get("name") == crateName:
            crate = c
            break
    if not crate:
        _audit(endpoint, "error", error_code="NOT_FOUND", error_message="crate not found", start_ts=start)
        return _err("NOT_FOUND", "Crate not found")

    resolved_version = version
    if resolved_version is None:
        resolved_version = crate.get("latest_version")
        if not resolved_version:
            _audit(endpoint, "error", error_code="NOT_FOUND", error_message="no latest_version available for crate", start_ts=start)
            return _err("NOT_FOUND", "No latest version available for crate")

    crate_versions = _load("crate_versions.json")
    cv = None
    for v in crate_versions:
        if isinstance(v, dict) and v.get("crate_id") == crate.get("id") and v.get("version") == resolved_version:
            cv = v
            break
    if not cv:
        _audit(endpoint, "error", error_code="NOT_FOUND", error_message="crate version not found", start_ts=start)
        return _err("NOT_FOUND", "Crate version not found")

    # Must be indexed/available per tool contract
    if cv.get("status") not in ("available", "indexed"):
        _audit(endpoint, "error", error_code="NOT_FOUND", error_message="crate version not indexed/available", start_ts=start)
        return _err("NOT_FOUND", "Crate version not indexed/available")

    symbols = _load("symbols.json")
    q = query.strip().lower()
    terms = [t for t in re.split(r"\s+", q) if t]
    if not terms:
        _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="query must contain non-whitespace characters", start_ts=start)
        return _err("VALIDATION_ERROR", "query must contain non-whitespace characters")

    def _score(sym):
        st = (sym.get("search_text") or "")
        st_l = st.lower()
        name_l = (sym.get("name") or "").lower()
        module_l = (sym.get("module_path") or "").lower()
        # Simple relevance: all terms must appear; score boosts for name/module matches and earlier occurrences.
        score = 0
        for t in terms:
            idx = st_l.find(t)
            if idx < 0:
                return None
            score += max(0, 200 - idx)  # earlier is better
            if name_l.startswith(t):
                score += 400
            elif t in name_l:
                score += 250
            if module_l.startswith(t):
                score += 120
            elif t in module_l:
                score += 60
        return score

    matches = []
    for s in symbols:
        if not isinstance(s, dict):
            continue
        if s.get("crate_version_id") != cv.get("id"):
            continue
        if s.get("status") != "active":
            continue
        sc = _score(s)
        if sc is None:
            continue
        matches.append((sc, (s.get("name") or ""), s))

    matches.sort(key=lambda x: (-x[0], x[1].lower()))
    results = [m[2] for m in matches]

    resp = {
        "crate": {"id": crate.get("id"), "name": crate.get("name")},
        "version": {"id": cv.get("id"), "version": cv.get("version"), "status": cv.get("status")},
        "query": query,
        "results": results,
        "count": len(results),
    }
    _audit(endpoint, "ok", start_ts=start, meta={"crate_id": crate.get("id"), "crate_version_id": cv.get("id"), "count": len(results)})
    return resp

