def get_crate(crateName, **_extra):
    import json, os, datetime, time, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0348000" if __import__("os").path.isdir("./environment_mix/0348000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    endpoint = "get_crate"
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Request/usage log + rate limiting helpers (local, best-effort)
    def _norm_key(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        return s.strip()

    def _find_log_collection():
        # Schema didn't declare, but contract requires observable dynamics if present.
        # Use request_logs.json if it exists; otherwise create it on demand.
        fname = "request_logs.json"
        path = os.path.join(_DB, fname)
        return fname, os.path.exists(path)

    def _load_logs(fname):
        data = _load(fname)
        if isinstance(data, list):
            return data
        return []

    def _save_logs(fname, logs):
        _save(fname, logs)

    def _rate_check_and_log(status, credential_used, latency_ms):
        fname, exists = _find_log_collection()
        logs = _load_logs(fname) if exists else []
        # Simple rate limit: 120 requests/minute per credential_used (or 'ambient')
        key = credential_used or "ambient"
        cutoff = time.time() - 60.0
        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("credential_used") != key:
                continue
            ts = r.get("ts_unix")
            if isinstance(ts, (int, float)) and ts >= cutoff:
                recent += 1
        if recent >= 120:
            # Log the refused request too
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential_used": key,
                "status": "RATE_LIMIT",
                "latency_ms": int(latency_ms),
                "timestamp": now,
                "ts_unix": time.time()
            })
