        # Log normal request
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_used": key,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": now,
            "ts_unix": time.time()
        })
