        return None

    # Validate inputs
    if not isinstance(crateName, str) or len(crateName) < 1:
        latency_ms = (time.time() - started) * 1000.0
        rl = _rate_check_and_log("VALIDATION_ERROR", None, latency_ms)
        if rl:  # if rate limited, return that (service dynamics)
            return rl
        return _err("VALIDATION_ERROR", "crateName must be a non-empty string.", field="crateName")

    crates = _load("crates.json")
    crate = None
    for c in crates:
        if isinstance(c, dict) and c.get("name") == crateName:
            crate = c
            break

    if not crate:
        latency_ms = (time.time() - started) * 1000.0
        rl = _rate_check_and_log("NOT_FOUND", None, latency_ms)
        if rl:
            return rl
        return _err("NOT_FOUND", "Crate not found.", crateName=crateName)

    latency_ms = (time.time() - started) * 1000.0
    rl = _rate_check_and_log("OK", None, latency_ms)
    if rl:
        return rl

    return {
        "crate": crate
    }

def upsert_crate(apiKey, crateName, description=None, repository_url=None, homepage_url=None, documentation_url=None, downloads_total=None, latest_version=None, status=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0348000" if __import__("os").path.isdir("./environment_mix/0348000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    started = time.time()
    endpoint = "upsert_crate"
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
