        data = _load(fname)
        return data if isinstance(data, list) else []

    def _save_logs(fname, logs):
        _save(fname, logs)

    def _rate_check_and_log(status_code, credential_used, latency_ms):
        fname, exists = _find_log_collection()
        logs = _load_logs(fname) if exists else []
        key = credential_used or "ambient"
        cutoff = time.time() - 60.0
        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("credential_used") != key:
                continue
            ts = r.get("ts_unix")
            if isinstance(ts, (int, float)) and ts >= cutoff:
                recent += 1
        if recent >= 60:  # stricter for mutating operations
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential_used": key,
                "status": "RATE_LIMIT",
                "latency_ms": int(latency_ms),
                "timestamp": now,
                "ts_unix": time.time()
            })
            _save_logs(fname, logs)
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=60)
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_used": key,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": now,
            "ts_unix": time.time()
        })
        _save_logs(fname, logs)
        return None

    # Validate auth (explicit credential parameter)
    if not isinstance(apiKey, str) or len(apiKey) < 1:
        latency_ms = (time.time() - started) * 1000.0
        rl = _rate_check_and_log("VALIDATION_ERROR", None, latency_ms)
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string.", field="apiKey")

    # Authenticate against any supported local keys collection if present; otherwise accept as valid (offline service)
    credential_used = apiKey
    keys = None
    keys_file = None
    for candidate in ("api_keys.json", "keys.json", "auth_keys.json"):
        p = os.path.join(_DB, candidate)
        if os.path.exists(p):
            keys_file = candidate
            keys = _load(candidate)
            break
    if keys_file and isinstance(keys, list):
        ok = False
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == apiKey or k.get("key") == apiKey or k.get("value") == apiKey or k.get("token") == apiKey:
                # If a status field exists, require active
                if k.get("status") in (None, "active", "enabled", "valid"):
                    ok = True
                    credential_used = k.get("id") or apiKey
                    break
        if not ok:
            latency_ms = (time.time() - started) * 1000.0
            rl = _rate_check_and_log("UNAUTHORIZED", apiKey, latency_ms)
            if rl:
                return rl
            return _err("UNAUTHORIZED", "Invalid API key.")

    # Validate inputs
    if not isinstance(crateName, str) or len(crateName) < 1:
        latency_ms = (time.time() - started) * 1000.0
        rl = _rate_check_and_log("VALIDATION_ERROR", credential_used, latency_ms)
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "crateName must be a non-empty string.", field="crateName")

    if description is not None and not isinstance(description, str):
        latency_ms = (time.time() - started) * 1000.0
        rl = _rate_check_and_log("VALIDATION_ERROR", credential_used, latency_ms)
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "description must be a string.", field="description")

    for field_name, v in (("repository_url", repository_url), ("homepage_url", homepage_url), ("documentation_url", documentation_url)):
        if v is not None and not isinstance(v, str):
            latency_ms = (time.time() - started) * 1000.0
            rl = _rate_check_and_log("VALIDATION_ERROR", credential_used, latency_ms)
            if rl:
                return rl
            return _err("VALIDATION_ERROR", f"{field_name} must be a string.", field=field_name)

    if downloads_total is not None:
        if not isinstance(downloads_total, (int, float)) or isinstance(downloads_total, bool):
            latency_ms = (time.time() - started) * 1000.0
            rl = _rate_check_and_log("VALIDATION_ERROR", credential_used, latency_ms)
            if rl:
                return rl
            return _err("VALIDATION_ERROR", "downloads_total must be a number.", field="downloads_total")
        if int(downloads_total) < 0:
            latency_ms = (time.time() - started) * 1000.0
            rl = _rate_check_and_log("VALIDATION_ERROR", credential_used, latency_ms)
            if rl:
                return rl
            return _err("VALIDATION_ERROR", "downloads_total must be >= 0.", field="downloads_total")
        downloads_total = int(downloads_total)

    if latest_version is not None and not isinstance(latest_version, str):
        latency_ms = (time.time() - started) * 1000.0
        rl = _rate_check_and_log("VALIDATION_ERROR", credential_used, latency_ms)
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "latest_version must be a string or null.", field="latest_version")
    if latest_version is not None and len(latest_version) < 1:
        latency_ms = (time.time() - started) * 1000.0
        rl = _rate_check_and_log("VALIDATION_ERROR", credential_used, latency_ms)
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "latest_version must be a non-empty string when provided.", field="latest_version")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "disabled"):
            latency_ms = (time.time() - started) * 1000.0
            rl = _rate_check_and_log("VALIDATION_ERROR", credential_used, latency_ms)
            if rl:
                return rl
            return _err("VALIDATION_ERROR", "status must be one of: active, disabled.", field="status")

    crates = _load("crates.json")
    if not isinstance(crates, list):
        crates = []

    # Uniqueness constraint on name
    existing = None
    for c in crates:
        if isinstance(c, dict) and c.get("name") == crateName:
            existing = c
            break

    # Enforce latest_version FK constraint if set: must exist in crate_versions for this crate (existing or new crate)
    crate_versions = _load("crate_versions.json")
    if not isinstance(crate_versions, list):
        crate_versions = []

    def _crate_id_for(name):
        for c in crates:
            if isinstance(c, dict) and c.get("name") == name:
                return c.get("id")
        return None

    # Create or update
    if existing is None:
        crate_id = "crate_" + uuid.uuid4().hex
        # If latest_version provided, must exist for this crate_id (but doesn't yet). Reject unless null.
        if latest_version is not None:
            latency_ms = (time.time() - started) * 1000.0
            rl = _rate_check_and_log("VALIDATION_ERROR", credential_used, latency_ms)
            if rl:
                return rl
            return _err("VALIDATION_ERROR", "latest_version cannot be set on a new crate unless a matching crate_version exists.", field="latest_version")

        row = {
            "id": crate_id,
            "name": crateName,
            "description": description,
            "repository_url": repository_url,
            "homepage_url": homepage_url,
            "documentation_url": documentation_url,
            "downloads_total": downloads_total if downloads_total is not None else 0,
            "latest_version": None,
            "last_indexed_at": None,
            "status": status if status is not None else "active",
            "created_at": now,
            "updated_at": now
        }
        crates.append(row)
        _save("crates.json", crates)

        latency_ms = (time.time() - started) * 1000.0
        rl = _rate_check_and_log("OK", credential_used, latency_ms)
        if rl:
            return rl
        return {"crate": row, "created": True}
    else:
        # Prevent rename via upsert: crateName is the lookup key; no other name field exists, so OK.
        # Apply updates; if latest_version provided, verify it exists for this crate id.
        crate_id = existing.get("id")
        if latest_version is not None:
            ok = False
            for v in crate_versions:
                if isinstance(v, dict) and v.get("crate_id") == crate_id and v.get("version") == latest_version:
                    ok = True
                    break
            if not ok:
                latency_ms = (time.time() - started) * 1000.0
                rl = _rate_check_and_log("VALIDATION_ERROR", credential_used, latency_ms)
                if rl:
                    return rl
                return _err("VALIDATION_ERROR", "latest_version must match an existing crate_versions.version for this crate.", field="latest_version")

        # Update fields if provided (patch semantics)
        if description is not None:
            existing["description"] = description
        if repository_url is not None:
            existing["repository_url"] = repository_url
        if homepage_url is not None:
            existing["homepage_url"] = homepage_url
        if documentation_url is not None:
            existing["documentation_url"] = documentation_url
        if downloads_total is not None:
            existing["downloads_total"] = downloads_total
        if latest_version is not None or latest_version is None:
            # Only set if caller passed it explicitly; however, we cannot detect explicit None vs omitted here reliably
            # because default is None. Follow tool schema: latest_version is optional; keep unchanged when None.
            # So: only set when latest_version is a non-empty string.
            if isinstance(latest_version, str):
                existing["latest_version"] = latest_version
        if status is not None:
            # lifecycle transitions allowed active<->disabled
            cur = existing.get("status")
            if cur not in ("active", "disabled"):
                cur = "active"
            allowed = {"active": ["disabled"], "disabled": ["active"]}
            if status != cur and status not in allowed.get(cur, []):
                latency_ms = (time.time() - started) * 1000.0
                rl = _rate_check_and_log("INVALID_TRANSITION", credential_used, latency_ms)
                if rl:
                    return rl
                return _err("INVALID_TRANSITION", "Illegal status transition.", from_status=cur, to_status=status)
            existing["status"] = status

        if not isinstance(existing.get("name"), str) or len(existing.get("name")) < 1:
            latency_ms = (time.time() - started) * 1000.0
            rl = _rate_check_and_log("VALIDATION_ERROR", credential_used, latency_ms)
            if rl:
                return rl
            return _err("VALIDATION_ERROR", "Crate name invalid after update.", field="crateName")

        if int(existing.get("downloads_total") or 0) < 0:
            latency_ms = (time.time() - started) * 1000.0
            rl = _rate_check_and_log("VALIDATION_ERROR", credential_used, latency_ms)
            if rl:
                return rl
            return _err("VALIDATION_ERROR", "downloads_total must be >= 0.", field="downloads_total")

        existing["updated_at"] = now
        _save("crates.json", crates)

        latency_ms = (time.time() - started) * 1000.0
        rl = _rate_check_and_log("OK", credential_used, latency_ms)
        if rl:
            return rl
        return {"crate": existing, "created": False}

def refresh_crate_versions(apiKey, crateName, includeYanked=None, force=None, **_extra):
