    def _rate_check_and_log(status_code, credential_used, latency_ms):
        fname, exists = _find_log_collection()
        logs = _load_logs(fname) if exists else []
        key = credential_used or "ambient"
        cutoff = time.time() - 60.0
        recent = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("credential_used") != key:
                continue
            ts = r.get("ts_unix")
            if isinstance(ts, (int, float)) and ts >= cutoff:
                recent += 1
        if recent >= 30:  # heavier operation
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "credential_used": key,
                "status": "RATE_LIMIT",
                "latency_ms": int(latency_ms),
                "timestamp": now,
                "ts_unix": time.time()
            })
            _save_logs(fname, logs)
            return _err("RATE_LIMIT", "Rate limit exceeded. Please retry later.", limit_per_minute=30)
        logs.append({
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_used": key,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": now,
            "ts_unix": time.time()
        })
        _save_logs(fname, logs)
        return None

    # Validate inputs
    if not isinstance(apiKey, str) or len(apiKey) < 1:
        latency_ms = (time.time() - started) * 1000.0
        rl = _rate_check_and_log("VALIDATION_ERROR", None, latency_ms)
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string.", field="apiKey")

    if not isinstance(crateName, str) or len(crateName) < 1:
        latency_ms = (time.time() - started) * 1000.0
        rl = _rate_check_and_log("VALIDATION_ERROR", apiKey, latency_ms)
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "crateName must be a non-empty string.", field="crateName")

    if includeYanked is None:
        includeYanked = True
    if force is None:
        force = False
    if not isinstance(includeYanked, bool):
        latency_ms = (time.time() - started) * 1000.0
        rl = _rate_check_and_log("VALIDATION_ERROR", apiKey, latency_ms)
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "includeYanked must be a boolean.", field="includeYanked")
    if not isinstance(force, bool):
        latency_ms = (time.time() - started) * 1000.0
        rl = _rate_check_and_log("VALIDATION_ERROR", apiKey, latency_ms)
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "force must be a boolean.", field="force")

    # Authenticate if keys collection exists
    credential_used = apiKey
    keys = None
    keys_file = None
    for candidate in ("api_keys.json", "keys.json", "auth_keys.json"):
        p = os.path.join(_DB, candidate)
        if os.path.exists(p):
            keys_file = candidate
            keys = _load(candidate)
            break
    if keys_file and isinstance(keys, list):
        ok = False
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == apiKey or k.get("key") == apiKey or k.get("value") == apiKey or k.get("token") == apiKey:
                if k.get("status") in (None, "active", "enabled", "valid"):
                    ok = True
                    credential_used = k.get("id") or apiKey
                    break
        if not ok:
            latency_ms = (time.time() - started) * 1000.0
            rl = _rate_check_and_log("UNAUTHORIZED", apiKey, latency_ms)
            if rl:
                return rl
            return _err("UNAUTHORIZED", "Invalid API key.")

    crates = _load("crates.json")
    if not isinstance(crates, list):
        crates = []
    crate = None
    for c in crates:
        if isinstance(c, dict) and c.get("name") == crateName:
            crate = c
            break
    if not crate:
        latency_ms = (time.time() - started) * 1000.0
        rl = _rate_check_and_log("NOT_FOUND", credential_used, latency_ms)
        if rl:
            return rl
        return _err("NOT_FOUND", "Crate not found.", crateName=crateName)

    crate_versions = _load("crate_versions.json")
    if not isinstance(crate_versions, list):
        crate_versions = []

    # Offline "refresh": we cannot contact upstream. Real behavior: upsert fetched versions.
    # Implement refresh by "touching" existing versions for the crate and ensuring required fields shape;
    # optionally insert a placeholder version if none exist, only when force=True (maintenance mode).
    crate_id = crate.get("id")
    touched = 0
    inserted = 0

    # Build index for existing versions by version string
    existing_by_ver = {}
    for v in crate_versions:
        if isinstance(v, dict) and v.get("crate_id") == crate_id and isinstance(v.get("version"), str):
            existing_by_ver[v["version"]] = v

    if not existing_by_ver and force:
        # Insert a placeholder "0.0.0" to allow subsequent workflows in offline mode
        placeholder_ver = "0.0.0"
        if placeholder_ver not in existing_by_ver:
            row = {
                "id": "ver_" + uuid.uuid4().hex,
                "crate_id": crate_id,
                "version": placeholder_ver,
                "yanked": False,
                "published_at": None,
                "rust_version": None,
                "checksum": None,
                "features": {},
                "doc_base_url": None,
                "status": "available",
                "last_error": None,
                "indexed_at": None,
                "created_at": now,
                "updated_at": now
            }
            crate_versions.append(row)
            inserted += 1
            existing_by_ver[placeholder_ver] = row

    # "Refresh" existing versions: normalize fields, optionally drop yanked if includeYanked=False (API layer choice)
    for ver, row in list(existing_by_ver.items()):
        # Ensure features is an object
        if not isinstance(row.get("features"), dict):
            row["features"] = {}
            touched += 1
        # Ensure yanked boolean
        if not isinstance(row.get("yanked"), bool):
            row["yanked"] = False
            touched += 1
        # Ensure status valid
        if row.get("status") not in ("available", "indexing", "indexed", "failed", "disabled"):
            row["status"] = "available"
            row["last_error"] = None
            row["indexed_at"] = None
            touched += 1
        # Enforce constraints for failed/indexed
        if row["status"] == "failed" and not row.get("last_error"):
            row["last_error"] = "Unknown indexing error (refreshed)."
            touched += 1
        if row["status"] == "indexed" and not row.get("indexed_at"):
            row["indexed_at"] = now
            touched += 1
        if touched:
            row["updated_at"] = now

    # Update crate.last_indexed_at (metadata sync time)
    crate["last_indexed_at"] = now
    crate["updated_at"] = now

    _save("crate_versions.json", crate_versions)
    _save("crates.json", crates)

    # If includeYanked is False, report versions count excluding yanked in response metadata only
    visible_versions = 0
    for v in crate_versions:
        if isinstance(v, dict) and v.get("crate_id") == crate_id:
            if includeYanked or not v.get("yanked", False):
                visible_versions += 1

    latency_ms = (time.time() - started) * 1000.0
    rl = _rate_check_and_log("OK", credential_used, latency_ms)
    if rl:
        return rl

    return {
        "crate": crate,
        "versions_inserted": inserted,
        "versions_updated": touched,
        "versions_visible": visible_versions
    }

