            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_used": key,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": now,
            "ts_unix": time.time()
        })
        _save_logs(fname, logs)
        return None

    # Validate inputs
    if not isinstance(apiKey, str) or len(apiKey) < 1:
        latency_ms = (time.time() - started) *  1000.0
        rl = _rate_check_and_log("VALIDATION_ERROR", None, latency_ms)
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string.", field="apiKey")

    if not isinstance(crateName, str) or len(crateName) < 1:
        latency_ms = (time.time() - started) *  1000.0
        rl = _rate_check_and_log("VALIDATION_ERROR", apiKey, latency_ms)
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "crateName must be a non-empty string.", field="crateName")

    if version is not None and (not isinstance(version, str) or len(version) < 1):
        latency_ms = (time.time() - started) *  1000.0
        rl = _rate_check_and_log("VALIDATION_ERROR", apiKey, latency_ms)
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "version must be a non-empty string when provided.", field="version")

    if priority is None:
        priority = "normal"
    if not isinstance(priority, str) or priority not in ("low", "normal", "high"):
        latency_ms = (time.time() - started) *  1000.0
        rl = _rate_check_and_log("VALIDATION_ERROR", apiKey, latency_ms)
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "priority must be one of: low, normal, high.", field="priority")

    if reason is not None and not isinstance(reason, str):
        latency_ms = (time.time() - started) *  1000.0
        rl = _rate_check_and_log("VALIDATION_ERROR", apiKey, latency_ms)
        if rl:
            return rl
        return _err("VALIDATION_ERROR", "reason must be a string.", field="reason")

    # Authenticate if keys collection exists
    credential_used = apiKey
    keys = None
    keys_file = None
    for candidate in ("api_keys.json", "keys.json", "auth_keys.json"):
        p = os.path.join(_DB, candidate)
        if os.path.exists(p):
            keys_file = candidate
            keys = _load(candidate)
            break
    if keys_file and isinstance(keys, list):
        ok = False
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == apiKey or k.get("key") == apiKey or k.get("value") == apiKey or k.get("token") == apiKey:
                if k.get("status") in (None, "active", "enabled", "valid"):
                    ok = True
                    credential_used = k.get("id") or apiKey
                    break
        if not ok:
            latency_ms = (time.time() - started) *  1000.0
            rl = _rate_check_and_log("UNAUTHORIZED", apiKey, latency_ms)
            if rl:
                return rl
            return _err("UNAUTHORIZED", "Invalid API key.")

    crates = _load("crates.json")
    if not isinstance(crates, list):
        crates = []
    crate = None
    for c in crates:
        if isinstance(c, dict) and c.get("name") == crateName:
            crate = c
            break
    if not crate:
        latency_ms = (time.time() - started) *  1000.0
        rl = _rate_check_and_log("NOT_FOUND", credential_used, latency_ms)
        if rl:
            return rl
        return _err("NOT_FOUND", "Crate not found.", crateName=crateName)

    # Resolve version if omitted
    if version is None:
        lv = crate.get("latest_version")
        if not lv:
            latency_ms = (time.time() - started) *  1000.0
            rl = _rate_check_and_log("NOT_FOUND", credential_used, latency_ms)
            if rl:
                return rl
            return _err("NOT_FOUND", "No latest_version set for crate; version must be specified.", crateName=crateName)
        version = lv

    crate_versions = _load("crate_versions.json")
    if not isinstance(crate_versions, list):
        crate_versions = []

    cv = None
    for v in crate_versions:
        if isinstance(v, dict) and v.get("crate_id") == crate.get("id") and v.get("version") == version:
            cv = v
            break
    if not cv:
        latency_ms = (time.time() - started) *  1000.0
        rl = _rate_check_and_log("NOT_FOUND", credential_used, latency_ms)
        if rl:
            return rl
        return _err("NOT_FOUND", "Crate version not found.", crateName=crateName, version=version)

    # Disabled versions cannot be indexed (tool says CONFLICT)
    if cv.get("status") == "disabled":
        latency_ms = (time.time() - started) *  1000.0
        rl = _rate_check_and_log("CONFLICT", credential_used, latency_ms)
        if rl:
            return rl
        return _err("CONFLICT", "Crate version is disabled and cannot be indexed.", crateName=crateName, version=version)

    # Lifecycle transition to indexing must be valid
    cur = cv.get("status")
    allowed = {
        "available": ["indexing", "disabled"],
        "indexing": ["indexed", "failed", "disabled"],
        "indexed": ["indexing", "disabled"],
        "failed": ["indexing", "disabled"],
        "disabled": ["available"]
    }
    if cur not in allowed:
        cur = "available"
        cv["status"] = cur
    if "indexing" not in allowed.get(cur, []):
        latency_ms = (time.time() - started) *  1000.0
        rl = _rate_check_and_log("INVALID_TRANSITION", credential_used, latency_ms)
        if rl:
            return rl
        return _err("INVALID_TRANSITION", "Illegal status transition to indexing.", from_status=cur, to_status="indexing")

    # Idempotent: if already indexing, do not "succeed without effect"—but can return current job state if job exists.
    # We'll create/enqueue a job record; if already indexing and a pending job exists, return it.
    jobs_file = "index_jobs.json"
    jobs_path = os.path.join(_DB, jobs_file)
    jobs = _load(jobs_file) if os.path.exists(jobs_path) else []
    if not isinstance(jobs, list):
        jobs = []

    existing_job = None
    for j in reversed(jobs):
        if not isinstance(j, dict):
            continue
        if j.get("crate_version_id") == cv.get("id") and j.get("status") in ("queued", "running"):
            existing_job = j
            break

    if cur == "indexing" and existing_job is not None:
        latency_ms = (time.time() - started) *  1000.0
        rl = _rate_check_and_log("OK", credential_used, latency_ms)
        if rl:
            return rl
        return {
            "crate": crate,
            "crate_version": cv,
            "job": existing_job,
            "enqueued": False
        }

    # Transition to indexing and enqueue job
    cv["status"] = "indexing"
    cv["last_error"] = None
    cv["updated_at"] = now
    # indexed_at stays as-is until successful indexing completes

    job = {
        "id": "job_" + uuid.uuid4().hex,
        "crate_id": crate.get("id"),
        "crate_name": crateName,
        "crate_version_id": cv.get("id"),
        "version": version,
        "priority": priority,
        "reason": reason,
        "status": "queued",
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)

    _save("crate_versions.json", crate_versions)
    _save(jobs_file, jobs)

    latency_ms = (time.time() - started) *  1000.0
    rl = _rate_check_and_log("OK", credential_used, latency_ms)
    if rl:
        return rl

    return {
        "crate": crate,
        "crate_version": cv,
        "job": job,
        "enqueued": True
    }

def update_crate_version_status(apiKey, crateName, status, version=None, last_error=None, indexed_at=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0348000" if __import__("os").path.isdir("./environment_mix/0348000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt_to_store(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        s = s.strip()
        try:
            if s.endswith("Z"):
                dt = datetime.datetime.fromisoformat(s[:-1])
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                else:
                    dt = dt.astimezone(datetime.timezone.utc)
            else:
                dt = datetime.datetime.fromisoformat(s)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
                dt = dt.astimezone(datetime.timezone.utc)
            dt = dt.replace(microsecond=0)
            return dt.isoformat().replace("+00:00", "Z")
        except Exception:
            return None

    def _pick_logfile():
        for fname in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json"):
            if os.path.exists(os.path.join(_DB, fname)):
                return fname
        return "request_logs.json"

    def _audit(endpoint, status_str, credential_id=None, error_code=None, error_message=None, meta=None, start_ts=None):
        fname = _pick_logfile()
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        latency_ms = None
        if start_ts is not None:
            latency_ms = int(max(0, (time.time() - start_ts) * 1000))
        logs.append({
            "id": "req_" + str(int(time.time() * 1000)) + "_" + str(len(logs) + 1),
            "endpoint": endpoint,
            "status": status_str,
            "credential_id": credential_id,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "timestamp": _now_iso(),
            "meta": meta or {},
        })
        _save(fname, logs)

    def _enforce_rate_limit(endpoint, start_ts):
        fname = _pick_logfile()
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []

        now = datetime.datetime.utcnow().replace(tzinfo=datetime.timezone.utc)
        one_min_ago = now - datetime.timedelta(minutes=1)
        one_day_ago = now - datetime.timedelta(days=1)

        def _parse_ts(ts):
            if not isinstance(ts, str):
                return None
            try:
                if ts.endswith("Z"):
                    dt = datetime.datetime.fromisoformat(ts[:-1])
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    else:
                        dt = dt.astimezone(datetime.timezone.utc)
                else:
                    dt = datetime.datetime.fromisoformat(ts)
                    if dt.tzinfo is None:
                        dt = dt.replace(tzinfo=datetime.timezone.utc)
                    dt = dt.astimezone(datetime.timezone.utc)
                return dt
            except Exception:
                return None

        last_min = 0
        last_day = 0
        for r in logs:
            dt = _parse_ts(r.get("timestamp"))
            if not dt:
                continue
            if dt >= one_min_ago:
                last_min += 1
            if dt >= one_day_ago:
                last_day += 1

        if last_min >= 120:
            _audit(endpoint, "error", error_code="RATE_LIMIT", error_message="Rate limit exceeded (120 requests/min)", start_ts=start_ts)
            return _err("RATE_LIMIT", "Rate limit exceeded")
        if last_day >= 10000:
            _audit(endpoint, "error", error_code="QUOTA_EXCEEDED", error_message="Daily quota exceeded (10000 requests/day)", start_ts=start_ts)
            return _err("QUOTA_EXCEEDED", "Quota exceeded")
        return None

    start = time.time()
    endpoint = "update_crate_version_status"

    # Validate inputs
    if not isinstance(apiKey, str) or not apiKey.strip():
        _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="apiKey must be a non-empty string", start_ts=start)
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string")
    if not isinstance(crateName, str) or len(crateName) < 1:
        _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="crateName must be a non-empty string", start_ts=start)
        return _err("VALIDATION_ERROR", "crateName must be a non-empty string")
    allowed_status = {"available", "indexing", "indexed", "failed", "disabled"}
    if status not in allowed_status:
        _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="Invalid status", start_ts=start)
        return _err("VALIDATION_ERROR", "Invalid status", allowed=list(sorted(allowed_status)))

    if version is not None and (not isinstance(version, str) or not version.strip()):
        _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="version must be a non-empty string when provided", start_ts=start)
        return _err("VALIDATION_ERROR", "version must be a non-empty string when provided")

    if last_error is not None and not isinstance(last_error, str):
        _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="last_error must be a string or null", start_ts=start)
        return _err("VALIDATION_ERROR", "last_error must be a string or null")

    parsed_indexed_at = _parse_dt_to_store(indexed_at) if indexed_at is not None else None
    if indexed_at is not None and parsed_indexed_at is None:
        _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="indexed_at must be an RFC3339 date-time string or null", start_ts=start)
        return _err("VALIDATION_ERROR", "indexed_at must be a date-time string or null")

    # Enforce indexed_at business rule from tool description
    if status == "indexed":
        if parsed_indexed_at is None:
            _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="indexed_at is required when status='indexed'", start_ts=start)
            return _err("VALIDATION_ERROR", "indexed_at is required when status='indexed'")
    else:
        if indexed_at is not None and parsed_indexed_at is not None:
            _audit(endpoint, "error", error_code="VALIDATION_ERROR", error_message="indexed_at must be omitted or null unless status='indexed'", start_ts=start)
            return _err("VALIDATION_ERROR", "indexed_at must be omitted or null unless status='indexed'")

    rl = _enforce_rate_limit(endpoint, start)
    if rl:
        return rl

    # "Authenticate" apiKey:
    # Real vendor param is apiKey; in this datastore there is no dedicated keys table.
    # Accept any non-empty apiKey (do not compare against ciphertext/hashes). Record it in audit meta.
    credential_id = apiKey.strip()

    crates = _load("crates.json")
    crate_versions = _load("crate_versions.json")
    doc_pages = _load("doc_pages.json")
    symbols = _load("symbols.json")

    if not isinstance(crates, list):
        crates = []
    if not isinstance(crate_versions, list):
        crate_versions = []
    if not isinstance(doc_pages, list):
        doc_pages = []
    if not isinstance(symbols, list):
        symbols = []

    name_l = crateName.strip().lower()
    matching = [c for c in crates if isinstance(c, dict) and isinstance(c.get("name"), str) and c.get("name").lower() == name_l]
    if not matching:
        _audit(endpoint, "error", credential_id=credential_id, error_code="NOT_FOUND", error_message="Crate not found", start_ts=start, meta={"crateName": crateName})
        return _err("NOT_FOUND", "Crate not found")

    # Prefer crate that actually contains the version to avoid "picked wrong context" defects.
    requested_version = version.strip() if isinstance(version, str) else None

    def _find_crate_version_for_crate(crow, ver):
        if ver is None:
            ver = crow.get("latest_version")
            if not ver:
                return None, None
        for v in crate_versions:
            if isinstance(v, dict) and v.get("crate_id") == crow.get("id") and v.get("version") == ver:
                return v, ver
        return None, ver

    selected_crate = None
    selected_crv = None
    resolved_ver = requested_version
    if requested_version is not None:
        for c in matching:
            v, _ = _find_crate_version_for_crate(c, requested_version)
            if v:
                selected_crate, selected_crv, resolved_ver = c, v, requested_version
                break
    else:
        # If version omitted, choose a crate row whose latest_version exists and has a crate_version row
        for c in matching:
            v, ver_used = _find_crate_version_for_crate(c, None)
            if v:
                selected_crate, selected_crv, resolved_ver = c, v, ver_used
                break

    if not selected_crate or not selected_crv:
        # If version omitted and latest_version null -> NOT_FOUND (business rule)
        if requested_version is None:
            # Determine whether all candidates have latest_version null
            all_null = True
            for c in matching:
                if c.get("latest_version"):
                    all_null = False
                    break
            if all_null:
                _audit(endpoint, "error", credential_id=credential_id, error_code="NOT_FOUND", error_message="Crate latest_version is null; version must be specified", start_ts=start, meta={"crateName": crateName})
                return _err("NOT_FOUND", "Crate version not found (latest_version is null)")
        _audit(endpoint, "error", credential_id=credential_id, error_code="NOT_FOUND", error_message="Crate version not found", start_ts=start, meta={"crateName": crateName, "version": requested_version})
        return _err("NOT_FOUND", "Crate version not found")

    current = selected_crv.get("status")
    transitions = {
        "available": ["indexing", "disabled"],
        "indexing": ["indexed", "failed", "disabled"],
        "indexed": ["indexing", "disabled"],
        "failed": ["indexing", "disabled"],
        "disabled": ["available"],
    }
    if current not in transitions:
        _audit(endpoint, "error", credential_id=credential_id, error_code="VALIDATION_ERROR", error_message="Current status is invalid", start_ts=start, meta={"current": current})
        return _err("VALIDATION_ERROR", "Current status is invalid")

    # Idempotency: setting the same status is allowed; still update timestamps/fields consistently.
    if status != current and status not in transitions.get(current, []):
        _audit(
            endpoint, "error", credential_id=credential_id,
            error_code="INVALID_TRANSITION",
            error_message=f"Illegal status transition {current!r} -> {status!r}",
            start_ts=start,
            meta={"from": current, "to": status}
        )
        return _err("INVALID_TRANSITION", f"Illegal status transition from '{current}' to '{status}'")

    # Enforce status-dependent constraints
    if status == "failed":
        # schema: status='failed' implies last_error not null
        if last_error is None or (isinstance(last_error, str) and not last_error.strip()):
            _audit(endpoint, "error", credential_id=credential_id, error_code="VALIDATION_ERROR", error_message="last_error is required when status='failed'", start_ts=start)
            return _err("VALIDATION_ERROR", "last_error is required when status='failed'")
    if status == "indexed":
        # schema: status='indexed' implies indexed_at not null (already ensured)
        # business rule: must have at least one present doc page and symbols count > 0 (unless crate is empty)
        crv_id = selected_crv.get("id")
        present_docs = 0
        for p in doc_pages:
            if isinstance(p, dict) and p.get("crate_version_id") == crv_id and p.get("status") == "present":
                present_docs += 1
                break

        active_syms = 0
        for s in symbols:
            if isinstance(s, dict) and s.get("crate_version_id") == crv_id and s.get("status") == "active":
                active_syms += 1
                break

        # "unless crate is empty": approximate emptiness as having no doc_pages AND no symbols rows at all for that version
        any_docs = any(isinstance(p, dict) and p.get("crate_version_id") == crv_id for p in doc_pages)
        any_syms = any(isinstance(s, dict) and s.get("crate_version_id") == crv_id for s in symbols)
        is_empty = (not any_docs) and (not any_syms)

        if not is_empty:
            if present_docs < 1 or active_syms < 1:
                _audit(
                    endpoint, "error", credential_id=credential_id,
                    error_code="CONFLICT",
                    error_message="Cannot set status='indexed' without required artifacts (present doc page and active symbol)",
                    start_ts=start,
                    meta={"present_docs": present_docs, "active_symbols": active_syms, "crate_version_id": crv_id}
                )
                return _err("CONFLICT", "Cannot mark as indexed: missing required artifacts", present_doc_pages=present_docs, active_symbols=active_syms)

    # Apply mutation (must have effect)
    mutated = False
    now = _now_iso()
    for i, v in enumerate(crate_versions):
        if not isinstance(v, dict):
            continue
        if v.get("id") != selected_crv.get("id"):
            continue

        new_row = dict(v)
        # status
        new_row["status"] = status

        # last_error handling
        if last_error is not None:
            # null clears; string sets
            if isinstance(last_error, str):
                new_row["last_error"] = last_error
            else:
                new_row["last_error"] = None
        else:
            # if marking failed and last_error provided earlier enforced; else keep existing
            if status != "failed":
                # allow leaving as-is unless explicitly cleared; real pipelines often keep last_error until cleared
                pass

        # indexed_at handling
        if status == "indexed":
            new_row["indexed_at"] = parsed_indexed_at
        else:
            # If transitioning away from indexed, keep indexed_at (historical) as real systems do; do not clear unless explicitly required (not in rules)
            pass

        # schema constraints: if status='failed' ensure last_error not null
        if new_row["status"] == "failed" and not new_row.get("last_error"):
            _audit(endpoint, "error", credential_id=credential_id, error_code="VALIDATION_ERROR", error_message="status='failed' requires last_error", start_ts=start)
            return _err("VALIDATION_ERROR", "status='failed' requires last_error")

        if new_row["status"] == "indexed" and not new_row.get("indexed_at"):
            _audit(endpoint, "error", credential_id=credential_id, error_code="VALIDATION_ERROR", error_message="status='indexed' requires indexed_at", start_ts=start)
            return _err("VALIDATION_ERROR", "status='indexed' requires indexed_at")

        new_row["updated_at"] = now
        crate_versions[i] = new_row
        selected_crv = new_row
        mutated = True
        break

    if not mutated:
        _audit(endpoint, "error", credential_id=credential_id, error_code="NOT_FOUND", error_message="Crate version not found for update", start_ts=start)
        return _err("NOT_FOUND", "Crate version not found")

    _save("crate_versions.json", crate_versions)

    # Also refresh crates.latest_version integrity if needed (do not overwrite unless it already points to this version)
    # and update crate.updated_at if change affected its latest version metadata.
    crates_mut = False
    for i, c in enumerate(crates):
        if not isinstance(c, dict):
            continue
        if c.get("id") != selected_crate.get("id"):
            continue
        c2 = dict(c)
        # keep latest_version as is; only bump updated_at to reflect related change
        c2["updated_at"] = now
        crates[i] = c2
        selected_crate = c2
        crates_mut = True
        break
    if crates_mut:
        _save("crates.json", crates)

    resp = {
        "crate": {"id": selected_crate.get("id"), "name": selected_crate.get("name"), "status": selected_crate.get("status")},
        "crate_version": {
            "id": selected_crv.get("id"),
            "crate_id": selected_crv.get("crate_id"),
            "version": selected_crv.get("version"),
            "status": selected_crv.get("status"),
            "yanked": selected_crv.get("yanked"),
            "last_error": selected_crv.get("last_error"),
            "indexed_at": selected_crv.get("indexed_at"),
            "updated_at": selected_crv.get("updated_at"),
        }
    }
    _audit(endpoint, "ok", credential_id=credential_id, start_ts=start, meta={"crateName": crateName, "version": resolved_ver, "new_status": status})
    return resp
